func MakeChain(input []Domino) ([]Domino, bool) {
    n := len(input)
    if n == 0 {
        return []Domino{}, true
    }

    // adjacency list: vertex -> list of edge indices
    adj := make(map[int][]int)
    for i, d := range input {
        adj[d[0]] = append(adj[d[0]], i)
        adj[d[1]] = append(adj[d[1]], i)
    }

    // every vertex must have even degree
    for _, edges := range adj {
        if len(edges)%2 != 0 {
            return nil, false
        }
    }

    // connectivity: all vertices with edges must be reachable
    start := 0
    for v := range adj {
        start = v
        break
    }
    // BFS
    visited := make(map[int]bool)
    queue := []int{start}
    visited[start] = true
    for len(queue) > 0 {
        v := queue[0]
        queue = queue[1:]
        for _, ei := range adj[v] {
            other := input[ei][0]
            if input[ei][0] == v {
                other = input[ei][1]
            }
            if !visited[other] {
                visited[other] = true
                queue = append(queue, other)
            }
        }
    }
    for v := range adj {
        if !visited[v] {
            return nil, false
        }
    }

    // Hierholzer's algorithm
    used := make([]bool, n)
    var circuit []int // vertices in order
    stack := []int{start}

    for len(stack) > 0 {
        v := stack[len(stack)-1]
        // find an unused edge from v
