        for ei := range adj[v] {
            edge := adj[v][ei]
            if !used[edge] {
                used[edge] = true
                other := input[edge][0]
                if input[edge][0] == v {
                    other = input[edge][1]
                }
                stack = append(stack, other)
                found = true
                break
            }
        }
        if !found {
            circuit = append(circuit, v)
            stack = stack[:len(stack)-1]
        }
    }

    // circuit is in reverse order
    // circuit has n+1 vertices (start ... start)
    // build dominoes from consecutive vertices
    // reverse circuit
    for i, j := 0, len(circuit)-1; i < j; i, j = i+1, j-1 {
        circuit[i], circuit[j] = circuit[j], circuit[i]
    }

    chain := make([]Domino, n)
    for i := 0; i < n; i++ {
        chain[i] = Domino{circuit[i], circuit[i+1]}
    }

    return chain, true
}
